    },
    {
      "card_ids": ["C58"],
      "claim": "Riluzole, a heteroaromatic primary amine with some first-pass metabolism, shows about 60% absolute oral bioavailability in humans, supporting high bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C29"],
      "claim": "Tolfenamic acid, a dichlorophenyl-containing carboxylic acid, has an absolute oral bioavailability of 55.6% in healthy volunteers, supporting F >= 20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C48"],
      "claim": "Saccharin, despite being structurally simple, shows 84% absolute oral bioavailability in humans, providing high-transfer evidence that small polar heteroaromatic molecules can be well absorbed orally.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C56"],
      "claim": "Cladribine, a polar heteroaromatic amine with transporter-related absorption limitations, still achieves 37-51% absolute oral bioavailability, remaining well above the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues show oral bioavailability values well above 20%, with the most relevant antiepileptic and heteroaromatic amine analogues (rufinamide 85%, riluzole 60%) strongly supporting a high F prediction for the query.",
